var t=[{key:"newton-cotes",nombre:"F\xF3rmulas de Newton-Cotes",principio:"El \xE1rea se aproxima por trozos: trapecios o par\xE1bolas entre puntos igualmente espaciados.",descripcion:"Se divide el intervalo [a, b] en n subintervalos de ancho h y se reemplaza la funci\xF3n por una pieza simple en cada trozo. El trapecio usa una recta entre dos puntos; Simpson, una par\xE1bola entre tres. Cuantos m\xE1s trozos, m\xE1s fino el resultado: el error baja como h\xB2 en trapecio y como h\u2074 en Simpson."}],a=[{key:"trapecio",nombre:"Regla del trapecio compuesta",ruta:"trapecio",familia:"newton-cotes",idea:"Une cada par de puntos consecutivos con una recta y suma el \xE1rea de los trapecios.",formula:"I \u2248 (h/2) \xB7 [f(x\u2080) + 2f(x\u2081) + \u2026 + f(x\u2099)]",formulaTex:"I \\approx \\frac{h}{2}\\left[f(x_0)+2f(x_1)+\\cdots+2f(x_{n-1})+f(x_n)\\right]",criterioTexto:"Error de orden h\xB2: al duplicar n, el error baja a la cuarta parte.",color:"#1b6b93"},{key:"simpson",nombre:"Regla de Simpson 1/3 compuesta",ruta:"simpson",familia:"newton-cotes",idea:"Ajusta una par\xE1bola cada tres puntos y suma el \xE1rea de esas par\xE1bolas.",formula:"I \u2248 (h/3) \xB7 [f(x\u2080) + 4f(x\u2081) + 2f(x\u2082) + \u2026 + f(x\u2099)]",formulaTex:"I \\approx \\frac{h}{3}\\left[f(x_0)+4f(x_1)+2f(x_2)+4f(x_3)+\\cdots+f(x_n)\\right]",criterioTexto:"Error de orden h\u2074: al duplicar n, el error baja a la dieciseisava parte. Exige n par.",color:"#8a5a00"}],i=a.reduce((o,e)=>(o[e.key]=e,o),{});function n(o){return a.filter(e=>e.familia===o)}function r(o){return`/modulo4/tipos/${o}`}function l(o){return`${r(o.familia)}/${o.ruta}/teoria`}export{t as a,a as b,n as c,r as d,l as e};
